            #region Combine
            public ErrorMask Combine(ErrorMask? rhs)
            {
                if (rhs == null) return this;
                var ret = new ErrorMask();
                ret.XALG = this.XALG.Combine(rhs.XALG);
                ret.FormTags = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.FormTags?.Overall, rhs.FormTags?.Overall), Noggog.ExceptionExt.Combine(this.FormTags?.Specific, rhs.FormTags?.Specific));
                ret.Race = this.Race.Combine(rhs.Race);
                ret.DNAM = this.DNAM.Combine(rhs.DNAM, (l, r) => l.Combine(r));
                ret.ENLM = this.ENLM.Combine(rhs.ENLM);
                ret.ENLT = this.ENLT.Combine(rhs.ENLT);
                ret.ENLS = this.ENLS.Combine(rhs.ENLS);
                ret.AUUV = this.AUUV.Combine(rhs.AUUV);
                ret.XFLG = this.XFLG.Combine(rhs.XFLG);
                ret.NAM0 = this.NAM0.Combine(rhs.NAM0);
                ret.NAM1 = this.NAM1.Combine(rhs.NAM1);
                ret.NAM2 = this.NAM2.Combine(rhs.NAM2);
                ret.NAM3 = this.NAM3.Combine(rhs.NAM3);
                ret.AdditionalRaces = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.AdditionalRaces?.Overall, rhs.AdditionalRaces?.Overall), Noggog.ExceptionExt.Combine(this.AdditionalRaces?.Specific, rhs.AdditionalRaces?.Specific));
                ret.FootstepSound = this.FootstepSound.Combine(rhs.FootstepSound);
                ret.ArtObject = this.ArtObject.Combine(rhs.ArtObject);
                ret.BSMP = this.BSMP.Combine(rhs.BSMP);
                ret.VONL = this.VONL.Combine(rhs.VONL);
                ret.BOD2 = this.BOD2.Combine(rhs.BOD2);
                ret.BSMB = this.BSMB.Combine(rhs.BSMB);
                ret.BSMS = this.BSMS.Combine(rhs.BSMS);
                ret.MO2C = this.MO2C.Combine(rhs.MO2C);
                ret.MO2F = this.MO2F.Combine(rhs.MO2F);
                ret.MO2S = this.MO2S.Combine(rhs.MO2S);
                ret.MO2T = this.MO2T.Combine(rhs.MO2T);
                ret.MO3C = this.MO3C.Combine(rhs.MO3C);
                ret.MO3F = this.MO3F.Combine(rhs.MO3F);
                ret.MO3S = this.MO3S.Combine(rhs.MO3S);
                ret.MO3T = this.MO3T.Combine(rhs.MO3T);
                ret.MO4S = this.MO4S.Combine(rhs.MO4S);
                ret.MO4T = this.MO4T.Combine(rhs.MO4T);
                ret.MO5S = this.MO5S.Combine(rhs.MO5S);
                ret.MO5T = this.MO5T.Combine(rhs.MO5T);
                ret.MOD2 = this.MOD2.Combine(rhs.MOD2);
                ret.MOD3 = this.MOD3.Combine(rhs.MOD3);
                ret.MOD4 = this.MOD4.Combine(rhs.MOD4);
