                sb.AppendLine($"ArmorAddon =>");
            }
            else
            {
                sb.AppendLine($"{name} (ArmorAddon) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
