        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IArmorAddonGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.Race, out var RaceInfo))
            {
                yield return RaceInfo;
            }
            if (FormLinkInformation.TryFactory(obj.NAM0, out var NAM0Info))
            {
                yield return NAM0Info;
            }
            if (FormLinkInformation.TryFactory(obj.NAM1, out var NAM1Info))
            {
                yield return NAM1Info;
            }
            foreach (var item in obj.AdditionalRaces)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.FootstepSound, out var FootstepSoundInfo))
            {
                yield return FootstepSoundInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ArtObject, out var ArtObjectInfo))
            {
                yield return ArtObjectInfo;
            }
            if (FormLinkInformation.TryFactory(obj.BSMP, out var BSMPInfo))
            {
                yield return BSMPInfo;
            }
            yield break;
        }
        
        #region Duplicate
        public ArmorAddon Duplicate(
            IArmorAddonGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new ArmorAddon(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
